<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {Theme,AppPage} from '@/domain/types';
import {assetUrl} from '@/services/api';
import {themeForPage,visualVariables,categoryPageKey,pageDesignFor,fixedModule} from '@/domain/visual';
import AppIcon from '@/components/AppIcon.vue';
import MobileTabBar from '@/components/MobileTabBar.vue';
import ThemeCarousel from '@/components/ThemeCarousel.vue';
import FilmModule from '@/components/FilmModule.vue';
const props=withDefaults(defineProps<{theme:Theme;page:string;state?:string;editing?:boolean;categoryEntry?:string}>(),{state:'normal'});
const emit=defineEmits<{group:[value:string];category:[id:string];navigate:[page:AppPage];design:[page:string]}>();
const selectedTab=ref('视频'),episode=ref(props.page==='shortdrama'?4:1),liked=ref(false),saved=ref(false),sheet=ref(''),expanded=ref(false),muted=ref(true),playing=ref(false),chat=ref(''),messages=ref<string[]>([]),shortTab=ref('短剧'),shortExpanded=ref(false),shortLiked=ref(false),shortSaved=ref(false);
const previewActions:Record<string,string>={'投屏':'此处预览设备列表样式。真实设备发现与连接由客户端投屏能力提供。','一起看':'此处预览创建房间与加入房间入口。真实房间及同步播放由运营服务和客户端共同提供。','耳机模式':'耳机模式需要客户端音频与后台播放能力。','下载':'下载任务需要可用片源与客户端离线下载能力。','分享':'正式客户端将分享当前影片链接。','消息通知':'未接入消息数据，当前没有真实未读数量。','扫一扫':'扫码需要客户端相机能力。','TV 登录':'正式客户端通过电视授权码完成登录。'};
watch(()=>props.page,()=>{sheet.value='';expanded.value=false;selectedTab.value='视频';episode.value=props.page==='shortdrama'?4:1;});
const appearancePage=computed(()=>props.page==='category'&&props.categoryEntry?categoryPageKey(props.categoryEntry):props.page);
const pageLayout=computed(()=>pageDesignFor(props.theme,appearancePage.value));
const effective=computed(()=>themeForPage(props.theme,appearancePage.value));
const style=computed(()=>({...visualVariables(effective.value),'--bg':effective.value.colors.background,'--text':effective.value.colors.text,'--muted':effective.value.colors.muted,'--accent':effective.value.colors.accent,'--surface':effective.value.colors.surface,'--mobile-nav':effective.value.colors.surface,backgroundSize:'cover',backgroundPosition:'center',backgroundImage:pageLayout.value.backgroundImage?'url("'+assetUrl(pageLayout.value.backgroundImage!)+ '")':undefined}));
const nav=computed(()=>props.theme.navigation.filter(n=>n.enabled));
const channels=computed(()=>props.theme.categories.filter(n=>n.enabled));
const currentChannel=computed(()=>props.page==='category'?channels.value.find(n=>n.id===props.categoryEntry):channels.value.find(n=>n.page===props.page));
const channel=computed(()=>currentChannel.value?.label||'');
function selectChannel(id:string){const item=channels.value.find(n=>n.id===id);if(!item)return;if(item.page==='category')emit('category',item.id);else emit('navigate',item.page);sheet.value='';}
function captureEditing(event:Event){if(!props.editing)return;if((event.target as Element).closest?.('.channel-tabs,.category-directory'))return;event.stopPropagation();event.preventDefault();const element=event.target as Element;const area=element.closest?.('.video-frame,.category-search,.profile-top,.channel-tabs,.hero-strip,.carousel,.home-highlights-block,.home-recommendations,.home-content,.membership,.mobile-tabbar');const module=element.closest?.('[data-module]')?.getAttribute('data-module');if(module){emit('group',module);return;}const classes=area?.classList;emit('group',classes?.contains('video-frame')?'player':classes?.contains('hero-strip')||classes?.contains('carousel')?'carousel':classes?.contains('home-highlights-block')?'home-highlights':classes?.contains('home-recommendations')?'home-recommendations':classes?.contains('home-content')?(props.page==='home'?'home-content':'cards'):classes?.contains('category-search')||classes?.contains('profile-top')?'appbar':classes?.contains('mobile-tabbar')?'navigation':classes?.contains('channel-tabs')?'directory':'cards');}
const categoryData:Record<string,{key:string;title:string;tagline:string;shortcuts:string[];titles:string[];counts:string[]}>={
 front:{key:'front',title:'嫁金钗',tagline:'古装爱情 · 真千金惊艳归来',shortcuts:['全部','排行榜','热播精选','新片速递','独播剧场'],titles:['此处通往繁星','嫁金钗','空枪'],counts:['更新至4集','更新至10集','独家首播']},
 tv:{key:'home',title:'秘密花园',tagline:'心动重逢 · 赴一场浪漫之约',shortcuts:['全部','排行榜','爆款系列','人间宝酷','港剧场','生花剧场','白夜剧场'],titles:['此处通往繁星','无可替代','一笑倾城'],counts:['10集全','20集全','30集全']},
 anime:{key:'anime',title:'开心锤锤世界',tagline:'开心每一天 · 一起畅游动画世界',shortcuts:['全部','排行榜','名侦探柯南','漫剧','加更礼','即将上线','国漫'],titles:['沧元图','光阴之外','东大高武学院'],counts:['更新至100话','更新至42话','更新至18话']},
 movie:{key:'movie',title:'虎影奇锋',tagline:'热血江湖 · 高燃动作大片震撼登场',shortcuts:['全部','N刷榜','IP系列','爱情新片','国庆档','金鸡奖','怪兽影厅'],titles:['空枪','老江湖','杯雪一战成名'],counts:['院线热映','动作佳作','独家首播']},
 variety:{key:'variety',title:'超正的我们',tagline:'热爱舞台的人 · 都在这里闪闪发光',shortcuts:['全部','排行榜','偏爱2抽好礼','超正的我们','24H放映厅','爆笑德云社','向野的我们'],titles:['偏爱之恋 第二季','游戏综艺王','这是我的西游2'],counts:['更新至10-23期','11期全','更新至10-22期']}
};
const activeCategory=computed(()=>props.page==='home'?'front':/动漫|少儿/.test(channel.value)?'anime':/电影/.test(channel.value)?'movie':/综艺/.test(channel.value)?'variety':'tv');
const catalog=computed(()=>categoryData[activeCategory.value]);
const isHome=computed(()=>props.page==='home');
const homeLayout=computed(()=>((props.theme.pageDesign?.home||{}) as any));
function homeModuleStyle(id:string){const m=homeLayout.value.modules?.[id.replace('home-','')]||{};return {background:m.background,'--module-text':m.textColor,'--module-title-size':m.titleSize===undefined?undefined:m.titleSize+'px','--module-radius':m.radius===undefined?undefined:m.radius+'px','--module-ratio':m.ratio};}
const homeModuleVisible=(id:string)=>homeLayout.value.modules?.[id.replace('home-','')]?.visible!==false;
const homeModuleTitle=(id:string,fallback:string)=>homeLayout.value.modules?.[id.replace('home-','')]?.title??fallback;
const homeModuleColumns=(id:string,fallback:number)=>Math.max(1,Math.min(4,Number(homeLayout.value.modules?.[id.replace('home-','')]?.columns??fallback)));
const homeModuleGap=(id:string,fallback:number)=>Math.max(0,Number(homeLayout.value.modules?.[id.replace('home-','')]?.gap??fallback));
const films=computed(()=>catalog.value.titles.map((title,i)=>({title,count:catalog.value.counts[i],note:['精选热播 · 不负期待','高能故事 · 正在热播','口碑推荐 · 精彩呈现'][i]})));
const heroNames=computed(()=>[catalog.value.key+'-hero',...(activeCategory.value==='front'?['movie-hero','variety-hero']:['front-hero','anime-hero'])]);
function sendChat(){if(chat.value.trim()){messages.value.push(chat.value.trim());chat.value='';}}
const pageSections=computed(()=>props.theme.sections.filter(s=>(s.page||'home')===props.page&&(!s.categoryEntry||s.categoryEntry===props.categoryEntry)));
const fixedIds=computed(()=>props.page==='home'?['home-highlights','home-recommendations','home-content']:['category-content']);
function hasModuleStyle(id:string){return !!pageLayout.value.modules?.[id.replace(/^(home|category)-/,'')]?.style;}
function fixedSection(id:string){return fixedModule(props.theme,appearancePage.value,id);}
const moduleIds=computed(()=>[...(props.page==='home'?['hero','home-highlights','home-recommendations','home-content']:['hero','category-content']),...pageSections.value.map(s=>s.id)]);
function moduleOrder(id:string){const saved=pageLayout.value.moduleOrder||[];const ids=[...saved.filter(id=>moduleIds.value.includes(id)),...moduleIds.value.filter(id=>!saved.includes(id))];return ids.indexOf(id)*2;}
const referenceCarousel=computed(()=>({...effective.value,carousel:{...effective.value.carousel,slides:effective.value.carousel.slides.length?effective.value.carousel.slides:heroNames.value.map((name,i)=>({id:'reference-'+i,vodId:'',title:i===0?catalog.value.title:'精彩好片，每天相见',image:img(name),video:'',page:'home' as const}))}}));
function referenceItems(categoryId=''){return Array.from({length:12},(_,i)=>({id:'reference-'+i,title:films.value[i%3].title,poster:img(catalog.value.key+'-poster-'+i%3),category:'离线参考素材',categoryId,year:'2026',area:'',note:films.value[i%3].count,score:'8.0',description:films.value[i%3].note,actors:'',director:'',sources:[]}));}
const referenceImage=(value:string)=>/^\/static\/skeleton-reference\/[a-z0-9-]+\.jpg$/.test(value)?value:assetUrl(value);
const referencePoster=(vod:{poster:string})=>/^\/static\/skeleton-reference\/[a-z0-9-]+\.jpg$/.test(vod.poster)?vod.poster:'';
const img=(name:string)=>'/static/skeleton-reference/'+name+'.jpg';
function select(group:string){if(props.editing)emit('group',group);}
function action(name:string){if(props.editing){emit('group',props.page==='player'?'player':'cards');return;}if(name==='一起看'){emit('design','together');return;}sheet.value=name;}
function filmOpen(){if(props.editing)emit('group','cards');else emit('design','player');}
function go(page:AppPage){if(props.editing)emit('group','navigation');else emit('navigate',page);}
</script>
<template>
<view class="reference-app" :class="{'player-page':['player','together'].includes(page),'home-page':isHome,'room-page':page==='together','shortdrama-page':page==='shortdrama'}" :style="style" @click.capture="captureEditing">
 <view class="reference-scroll">
 <template v-if="page==='player'||page==='together'">
  <view class="video-frame" :class="{'expanded-player':expanded}" @click="select('player')">
   <image class="player-scene" :src="img('player-scene')" mode="aspectFill"/><view class="video-shade"/><text class="player-watermark">{{effective.brand.name}}</text>
   <view class="video-top"><button aria-label="返回" @click.stop="page==='together'?sheet='退出房间':emit('navigate','home')"><AppIcon name="back" :color="String(effective.visual?.player?.controls||'#fff')"/></button><text class="player-caption">雪迷宫 {{String(episode).padStart(2,'0')}}</text><view class="spacer"/><button v-for="a in [{name:'投屏',icon:'tv'},{name:'一起看',icon:'together'},{name:'耳机模式',icon:'headphones'},{name:'更多',icon:'more'}]" :key="a.name" :aria-label="a.name" @click.stop="action(a.name)"><AppIcon :name="a.icon" :size="21" :color="String(effective.visual?.player?.controls||'#fff')"/></button></view>
   <view v-if="state!=='normal'" class="video-center"><AppIcon :name="state==='error'?'warning':state==='loading'?'refresh':'play'" :size="Number(effective.visual?.empty?.size||48)" :color="String(effective.visual?.empty?.color||effective.colors.muted)"/><text>{{state==='loading'?'正在加载':state==='error'?'播放失败':'暂无片源'}}</text></view>
   <view class="video-bottom"><view class="track"><view class="buffer"/><view class="progress"/></view><view class="video-controls"><button :aria-label="playing?'暂停预览':'播放预览'" @click.stop="playing=!playing">{{playing?'Ⅱ':'▶'}}</button><text>00:00 / --:--</text><view class="spacer"/><button @click.stop="action('全部选集')">选集</button><button @click.stop="action('换片')">换片</button><button aria-label="全屏" @click.stop="expanded=!expanded"><AppIcon name="scan" :size="19"/></button></view></view>

  </view>
  <template v-if="page==='together'">
   <view class="room-members"><view class="host-avatar"><image :src="img('avatar')" mode="aspectFill"/><text>房主 · 我</text></view><button class="invite-member" aria-label="邀请成员" @click="sheet='邀请好友'">＋</button></view>
   <view class="room-notice">文明观影，友善交流，共同维护温暖的观影环境。<button @click="sheet='一起看公约'">一起看公约 ›</button></view>
   <view class="room-invite"><text>一个人看，不如一起看</text><text>邀请好友加入房间，分享每一个精彩瞬间</text><button @click="sheet='邀请好友'">邀请好友</button></view>
   <view class="chat-messages"><view v-for="(message,i) in messages" :key="i"><text>我</text>{{message}}</view></view>
  </template>
  <view v-else class="play-info" @click="select('cards')">
   <view class="info-tabs"><button v-for="t in ['视频','讨论','看点']" :key="t" :class="{active:selectedTab===t}" @click="selectedTab=t">{{t}}<text v-if="t==='讨论'" class="comment-count">1049</text></button><view class="spacer"/><button class="gold-button" @click="action('会员续费')">年卡约5.1折</button></view>
   <template v-if="selectedTab==='视频'">
    <view class="title-row"><text class="film-title">雪迷宫</text><button class="intro" @click="action('影片简介')">简介 ›</button></view>
    <view class="metadata"><text>♨ 510</text><text><text class="blue">▶</text> 9.0分</text><text><text class="green">豆</text> 8.2分</text><text>都市爱情</text><text>青春竞技</text></view>
    <view class="film-actions"><button :aria-label="saved?'取消追剧':'追剧'" :class="{selected:saved}" @click="saved=!saved"><AppIcon name="listPlus" :size="25" :color="saved?theme.colors.accent:theme.colors.text"/></button><button aria-label="下载" @click="action('下载')"><AppIcon name="download" :size="25" :color="theme.colors.text"/></button><button aria-label="分享" @click="action('分享')"><AppIcon name="share" :size="25" :color="theme.colors.text"/></button><button :aria-label="liked?'取消点赞':'点赞'" :class="{selected:liked}" @click="liked=!liked"><AppIcon name="like" :size="25" :color="liked?theme.colors.accent:theme.colors.text"/></button></view>
    <view class="episode-title"><text>选集</text><button @click="action('全部选集')">16集全 ›</button></view>
    <view class="episodes"><button v-for="n in 16" :key="n" :class="{current:episode===n}" :aria-label="'第'+n+'集'" @click="episode=n"><view v-if="episode===n" class="equalizer"><i/><i/><i/></view><text v-else>{{n}}</text><text v-if="n>2" class="vip-tag">VIP</text></button></view>
    <view class="section-title">为你推荐</view><view class="poster-grid"><button v-for="(f,i) in films.slice(0,3)" :key="f.title" class="film-card" @click="filmOpen"><image :src="img('poster-'+i)" mode="aspectFill"/><text>{{f.title}}</text></button></view>
   </template>
   <view v-else class="tab-empty"><AppIcon :name="selectedTab==='讨论'?'together':'play'" :size="32" :color="theme.colors.muted"/><text>{{selectedTab==='讨论'?'讨论区':'精彩看点'}}</text><text>离线设计预览，暂无真实{{selectedTab==='讨论'?'讨论':'看点'}}数据</text></view>
  </view>
 </template>
 <template v-else-if="page==='mine'">
  <view class="profile-top" @click="select('appbar')"><view class="spacer"/><button v-for="a in [{name:'TV 登录',icon:'tv'},{name:'消息通知',icon:'bell'},{name:'扫一扫',icon:'scan'}]" :key="a.name" :aria-label="a.name" @click="action(a.name)"><AppIcon :name="a.icon" :size="23" :color="theme.colors.text"/></button></view>
  <view class="membership" @click="select('cards')"><text class="vip-watermark">SVIP</text><view class="profile-identity"><button class="avatar" aria-label="账号信息" @click="emit('design','login')"><image :src="theme.brand.logo?assetUrl(theme.brand.logo):img('avatar')" mode="aspectFill"/></button><view><text class="profile-name">小白不纯</text><text class="coins">🟡 酷金币: 0</text></view></view><view class="vip-bottom"><view><view class="vip-heading">SVIP会员 <text>权益尊享中</text></view><text class="vip-benefits">✦ SVIP提前看　▣ 电视可看　♟ 全家共享</text></view><button class="gold-button" @click="emit('design','recharge')">提前续费</button></view></view>
  <view class="profile-shortcuts" @click="select('cards')"><button v-for="a in [{name:'历史记录',icon:'history',page:'history'},{name:'我的下载',icon:'download',page:'downloads'},{name:'在追预约',icon:'schedule',page:'schedule'},{name:'我的收藏',icon:'favorite',page:'library'}]" :key="a.name" @click="a.page==='downloads'?emit('design','downloads'):go(a.page as AppPage)"><AppIcon :name="a.icon" :size="25" :color="theme.colors.text"/><text>{{a.name}}</text></button></view>
  <view class="history-list" @click="select('cards')"><button v-for="(f,i) in [{title:'嫁金钗 第10集',count:'更新至16集'},{title:'二十五，二十一 第01集',count:'16集全'},{title:'一拳超人 第三季 中配版 第09集',count:'12话全'}]" :key="f.title" @click="filmOpen"><view class="history-cover"><image :src="img('history-'+i)" mode="aspectFill"/><text>{{f.count}}</text></view><text class="history-caption">{{f.title}}</text></button></view>
  <view class="profile-note">会员信息、余额及观看记录为离线样式示例</view>
 </template>
 <template v-else-if="page==='shortdrama'">
  <view class="short-stage">
   <image class="short-backdrop" :src="img('shortdrama-scene')" mode="aspectFill"/>
   <view class="short-gradient"/>
   <view class="short-channels"><button v-for="name in ['看过','短视频','短剧','AI短剧','剧场','福利']" :key="name" :class="{active:shortTab===name}" @click="shortTab=name">{{name}}</button><button aria-label="搜索短剧" @click="go('search')"><AppIcon name="search" :size="23" color="#fff"/></button></view>
   <button class="short-play" :aria-label="playing?'暂停短剧预览':'播放短剧预览'" @click="playing=!playing"><AppIcon v-if="!playing" name="play" :size="40" color="#ffffff99"/></button>
   <view class="short-actions"><button :aria-label="shortSaved?'取消加追':'加追'" @click="shortSaved=!shortSaved"><AppIcon name="listPlus" :size="29" :color="shortSaved?theme.colors.accent:'#fff'"/><text>{{shortSaved?'已加追':'加追'}}</text></button><button :aria-label="shortLiked?'取消短剧点赞':'短剧点赞'" @click="shortLiked=!shortLiked"><AppIcon name="heart" :size="31" :color="shortLiked?'#ff5378':'#fff'"/><text>{{2558+(shortLiked?1:0)}}</text></button><button aria-label="短剧评论" @click="action('短剧评论')"><AppIcon name="message" :size="29" color="#fff"/><text>10</text></button></view>
   <view class="short-description"><button class="short-title" @click="action('短剧详情')"><image :src="img('front-poster-1')" mode="aspectFill"/><text>夜色里的探戈 ›</text></button><view class="short-tags"><text>赵慕颜</text><text>复仇</text><text>都市</text></view><view class="short-synopsis" :class="{expanded:shortExpanded}"><text>第{{episode}}集 | 关心的父母被何美慧害死，家业也被何美慧与顾南笙雀占鸠巢。多年后关心伪装成舞者归来，寻找真相。</text><button @click="shortExpanded=!shortExpanded">{{shortExpanded?'收起':'展开'}}</button></view></view>
   <button class="short-episodes" @click="sheet='短剧选集'"><AppIcon name="play" :size="15" color="#fff"/><text>观看完整短剧·30集</text><text>›</text></button>
  </view>
 </template>
 <template v-else>
  <view class="category-search" @click="select('appbar')"><button aria-label="菜单" @click="action('分类菜单')"><AppIcon name="menu" :color="theme.colors.text"/></button><button class="search-box" @click="go('search')"><AppIcon name="search" :size="18" :color="theme.colors.muted"/><text>搜索电影、电视剧、综艺</text><text class="search-filter">筛选</text></button><button class="brand-dot" @click="go('mine')">{{theme.brand.name.slice(0,1)}}</button></view>
  <view class="channel-tabs"><button v-for="c in channels" :key="c.id" :class="{active:currentChannel?.id===c.id}" @click="selectChannel(c.id)">{{c.label}}</button><button aria-label="更多分类" @click="action('全部分类')">⋮</button></view>
  <view class="page-modules">
  <view v-if="pageLayout?.carousel!==false" class="page-carousel" :style="{order:moduleOrder('hero')}" data-module="hero">
  <ThemeCarousel :theme="referenceCarousel" :image-resolver="referenceImage" :items="[]" native-mobile :editing="editing" @select="select('carousel')" @page="filmOpen" @id="filmOpen"/>
  </view>
